const occasionGiftSets: CatalogProduct[] = occasionGiftSetSpecs.map(([id, category, name, content, imageFileName, price, careKind]) => {
  const potted = careKind === 'potted';
  const dry = careKind === 'dry' || careKind === 'preserved';
  return {
    id, name, price, category, imageFileName,
    short: `${name}, ${content.charAt(0).toLocaleLowerCase('tr-TR')}${content.slice(1)}`,
    detailedDescription: `${content} Özenli sunumu ve birbiriyle uyumlu parçalarıyla özel anları sıcak bir hatıraya dönüştüren hazır bir hediye setidir.`,
    season: dry ? 'Dört mevsim' : 'Mevsiminde taze çiçeklerle dört mevsim hazırlanır',
    watering: dry ? '' : potted ? 'Toprağın üst kısmı kurudukça ölçülü sulayın' : 'Çiçek süngerini veya vazo suyunu düzenli kontrol edin',
    light: dry ? 'Rengini koruması için doğrudan güneşten uzak tutun' : 'Serin ve doğrudan güneş almayan aydınlık alan',
    environment: dry ? 'Kuru, serin ve nemden uzak iç mekân' : 'Isı kaynaklarından ve cereyandan uzak iç mekân',
    pot: potted ? 'Setle gelen drenajlı saksıyı kullanın' : '',
    soil: potted ? 'Geçirgen, bitki türüne uygun kaliteli saksı toprağı' : '',
    care: dry ? 'Kuru veya solmayan çiçeği sulamayın; tozunu yumuşak ve kuru bir fırçayla nazikçe alın.' : potted ? 'Canlı bitkiyi ambalajından çıkarın, tabağında su bekletmeyin ve ani sıcaklık değişiminden koruyun.' : 'Setteki taze çiçekleri serin tutun; solan parçaları temizleyin ve su seviyesini düzenli yenileyin.',
    meaning: category === 'Sevgiliye' ? 'Sevgiyi, birlikte geçirilen zamanı ve özenle kurulan bağı anlatır.' : 'Sevgi, minnet ve içten bir teşekkür ifadesidir.',
    badge: 'Özel hediye seti', stock: 12,
  };
});

const existingImageFileNames: Record<string, string> = {
  'Afrika menekşesi': 'afrika-menekse.png',
  'Kalanşo': ' kalanso.png',
};

const detailHiddenCategories = new Set([
  'Sevgiliye', 'Anneler Günü', 'Hediye Setleri', 'Yenilebilir & Çikolata',
  'Özel Günler', 'Saksı & Bakım', 'Bahçe & Çim',
]);

/** Kategori bantları fiyatları tutarlı tutar; her ürünün temel fiyatı yukarıdaki kaydından düzenlenebilir. */
function consistentPrice(product: CatalogProduct) {
  const price = product.price;
  if (product.category === 'Tohumlar') return Math.min(189, Math.max(59, price));
  if (product.category === 'Saksı & Bakım') return Math.min(1299, Math.max(249, price));
  if (product.category === 'Bahçe & Çim') return Math.min(1499, Math.max(299, price));
  if (['Sevgiliye', 'Anneler Günü', 'Hediye Setleri', 'Yenilebilir & Çikolata', 'Özel Günler'].includes(product.category)) {
    return Math.min(2999, Math.max(1099, price));
  }
  if (product.category === 'Sukulentler') return Math.min(1399, Math.max(349, price));
  if (product.category === 'Ev Bitkileri') return Math.min(2499, Math.max(599, price));
  return Math.min(2999, Math.max(499, price));
}

export function productImagePath(productName: string, imageFileName?: string) {
  if (imageFileName) return `/images/products/${encodeURIComponent(imageFileName.replace(/\.png$/i, ".jpg"))}`;
  const fileName = productName
    .toLocaleLowerCase('tr-TR')
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replaceAll('ı', 'i')
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-|-$/g, '');

  return `/images/products/${fileName}.jpg`;
}

export const allProducts: Product[] = productCatalog
  .filter((product) => product.category !== 'Sevgiliye' && product.category !== 'Anneler Günü')
  .concat(occasionGiftSets)
  .filter((product) => !(product.category === 'Doğum Günü' && product.name === 'Ayçiçeği'))
  .map((product) => {
    const imageFileName = existingImageFileNames[product.name];
    const isSeed = product.category === 'Tohumlar';
    const isCare = product.category === 'Saksı & Bakım';
    const isGarden = product.category === 'Bahçe & Çim';
    const isNonBotanicalGift = product.detailMode === 'nonBotanicalGift';
    const hideDetailSections = detailHiddenCategories.has(product.category);
    const productType: Product['productType'] = isSeed ? 'seed' : isCare ? 'care' : isGarden ? 'garden' : isNonBotanicalGift ? 'nonBotanicalGift' : 'botanical';
    const base = {
      ...product,
      price: consistentPrice(product),
      imageFileName,
      image: productImagePath(product.name, imageFileName),
      detailedDescription: product.detailedDescription || `${product.short} ${product.care}`,
      productType,
      showCareSection: !isNonBotanicalGift && !hideDetailSections,
      showRecommendations: !isNonBotanicalGift && !hideDetailSections,
    };
    if (!isCare) return base;
    return {
      ...base,
      short: `${product.name}, bitki bakımını düzenli ve pratik hâle getiren kullanışlı bir üründür.`,
      detailedDescription: `${product.name} ürününü kullanım talimatına uygun uygulayın; kullanım sonrasında temizleyip tamamen kurutarak kuru bir yerde saklayın.`,
      season: 'İhtiyaç oldukça dört mevsim kullanılabilir',
      care: 'Kullanım sonrasında temizleyip tamamen kurutun. Çocukların ve evcil hayvanların erişemeyeceği kuru bir yerde saklayın.',
      watering: 'Sulama gerektirmez',
      light: 'Doğrudan güneş ve yüksek ısıdan uzakta saklayın',
      environment: 'Kuru, serin ve havalandırılan saklama alanı',
      pot: 'Bu ürün için saksı seçimi gerekmez',
      soil: 'Etikette belirtilen kullanım alanına uygun toprakta uygulayın',
      meaning: 'Bakımlı ve sağlıklı bitkiler yetiştirmeyi destekler.',
    };
  });

/** Ana sayfadaki özgün seçki. */
export const products = allProducts.filter((product) => product.id < 1000);
